int longestNonOverlapBorder(const string& s){
    int n=s.size(); if(n==0) return 0;
    vector<int> lps(n,0);
    for(int i=1,len=0;i<n;){
        if(s[i]==s[len]) lps[i++]=++len;
        else if(len) len=lps[len-1];
        else lps[i++]=0;
    }
    int len=lps[n-1];
    while(len>n/2) len=lps[len-1];
    return len;
}

