string biggerIsGreater(string s){
    int n=s.size(), i=n-2;
    while(i>=0 && s[i]>=s[i+1]) i--;
    if(i<0) return "no answer";
    int j=n-1; while(s[j]<=s[i]) j--;
    swap(s[i],s[j]);
    reverse(s.begin()+i+1,s.end());
    return s;
}

int lengthOfLongestSubstring(const string& s){
    vector<int> last(256,-1); int l=0, ans=0;
    for(int r=0;r<(int)s.size();r++){
        unsigned char c=s[r];
        if(last[c]>=l) l=last[c]+1;
        last[c]=r; ans=max(ans,r-l+1);
    }
    return ans;
}

string multiply(const string& a,const string& b){
    if(a=="0"||b=="0") return "0";
    int n=a.size(), m=b.size(); vector<int> r(n+m,0);
    for(int i=n-1;i>=0;i--) for(int j=m-1;j>=0;j--){
        int p=(a[i]-'0')*(b[j]-'0')+r[i+j+1];
        r[i+j+1]=p%10; r[i+j]+=p/10;
    }
    string s; int k=0; while(k<n+m-1 && r[k]==0) k++;
    for(;k<n+m;k++) s+=char('0'+r[k]);
    return s;
}

