string longestUniqueSubstr(const string& s){
    vector<int> last(256,-1); int l=0, bestL=0, bestS=0;
    for(int r=0;r<(int)s.size();r++){
        unsigned char c=s[r];
        if(last[c]>=l) l=last[c]+1;
        last[c]=r;
        if(r-l+1>bestL){ bestL=r-l+1; bestS=l; }
    }
    return s.substr(bestS,bestL);
}

