string nextPalindrome(string s){
    int n=s.size();
    if(count(s.begin(),s.end(),'9')==n) return "1"+string(n-1,'0')+"1";
    string t=s;
    auto mirror=[&](){ for(int i=0;i<n/2;i++) t[n-1-i]=t[i]; };
    mirror();
    if(t>s) return t;
    int i=(n-1)/2;
    while(t[i]=='9'){ t[i]='0'; i--; }
    t[i]++;
    mirror();
    return t;
}

long long kSwitching(const string& s){
    int n=s.size(); vector<int> pre(n+1,0);
    for(int i=0;i<n;i++) pre[i+1]=pre[i]+(s[i]=='1');
    long long best=LLONG_MAX;
    for(int K=1;K<=n;K++){
        if(n%K) continue;
        long long c=0;
        for(int b=0;b*K<n;b++){
            int ones=pre[(b+1)*K]-pre[b*K];
            c+= (b%2==0)? ones : K-ones;
        }
        best=min(best,c);
    }
    return best;
}

string longestPalConcat(const vector<string>& v){
    unordered_set<string> st(v.begin(),v.end()), used;
    vector<string> left; string mid;
    for(const string& s: v){
        string r(s.rbegin(),s.rend());
        if(r==s){ if(s.size()>mid.size()||(s.size()==mid.size()&&s<mid)) mid=s; continue; }
        if(used.count(s)||!st.count(r)) continue;
        used.insert(s); used.insert(r); left.push_back(min(s,r));
    }
    sort(left.begin(),left.end());
    string L; for(auto& x: left) L+=x;
    return L+mid+string(L.rbegin(),L.rend());
}

long long groupCost(const string& s,char ch){
    vector<long long> q;
    for(int i=0;i<(int)s.size();i++) if(s[i]==ch) q.push_back(i-(long long)q.size());
    if(q.empty()) return 0;
    long long m=q[q.size()/2], c=0;
    for(long long x: q) c+=llabs(x-m);
    return c;
}
