int maxBalancedPieces(const string& s){
    int n=s.size(); vector<int> P(n+1,0);
    for(int i=0;i<n;i++) P[i+1]=P[i]+(s[i]=='L'?1:-1);
    int base=0; for(int i=1;i<=n;i++) base+=(P[i]==0);
    int best=base;
    for(int i=0;i+1<n;i++){
        if(s[i]==s[i+1]) continue;
        int nv=P[i]+(s[i+1]=='L'?1:-1);
        best=max(best, base-(P[i+1]==0)+(nv==0));
    }
    return best;
}

long long maxUniqueHash(const string& s){
    const long long MOD=1e9+7;
    int last[26]; bool in[26]={0}; string r;
    for(int i=0;i<(int)s.size();i++) last[s[i]-'a']=i;
    for(int i=0;i<(int)s.size();i++){
        int c=s[i]-'a'; if(in[c]) continue;
        while(!r.empty() && r.back()<s[i] && last[r.back()-'a']>i){ in[r.back()-'a']=false; r.pop_back(); }
        r.push_back(s[i]); in[c]=true;
    }
    long long h=0,p=1;
    for(char ch: r){ h=(h+(ch-'a'+1)*p)%MOD; p=p*31%MOD; }
    return h;
}

long long suffixMatchHash(const vector<string>& S,const string& q){
    const long long MOD=1e9+7;
    vector<array<int,26>> nx(1); nx[0].fill(-1); vector<vector<int>> ids(1);
    for(int k=0;k<(int)S.size();k++){ int u=0;
        for(int j=S[k].size()-1;j>=0;j--){ int c=S[k][j]-'a';
            if(nx[u][c]==-1){ nx[u][c]=nx.size(); nx.emplace_back(); nx.back().fill(-1); ids.emplace_back(); }
            u=nx[u][c]; }
        ids[u].push_back(k); }
    long long ans=0, pw=1;
    for(int i=0;i<(int)q.size();i++){ int u=0;
        for(int j=i;j>=0 && j>i-100;j--){ u=nx[u][q[j]-'a']; if(u==-1) break;
            for(int id: ids[u]){ ans=(ans+id%MOD*pw)%MOD; pw=pw*10%MOD; } } }
    return ans;
}

vector<pair<int,int>> palindromePairs(const vector<string>& w){
    auto isPal=[](const string& s,int l,int r){ while(l<r) if(s[l++]!=s[r--]) return false; return true; };
    unordered_map<string,int> mp;
    for(int i=0;i<(int)w.size();i++) mp[string(w[i].rbegin(),w[i].rend())]=i;
    vector<pair<int,int>> res;
    for(int i=0;i<(int)w.size();i++){
        int m=w[i].size();
        for(int k=0;k<=m;k++){
            if(isPal(w[i],k,m-1)){ auto it=mp.find(w[i].substr(0,k));
                if(it!=mp.end()&&it->second!=i) res.push_back({i,it->second}); }
            if(k>0 && isPal(w[i],0,k-1)){ auto it=mp.find(w[i].substr(k));
                if(it!=mp.end()&&it->second!=i) res.push_back({it->second,i}); }
        }
    }
    return res;
}

long long magicalVine(const string& s,long long K){
    int n=s.size(); vector<int> z(n,0); z[0]=n;
    for(int i=1,l=0,r=0;i<n;i++){
        if(i<r) z[i]=min(r-i,z[i-l]);
        while(i+z[i]<n && s[z[i]]==s[i+z[i]]) z[i]++;
        if(i+z[i]>r){ l=i; r=i+z[i]; }
    }
    vector<int> d(n+2,0);
    for(long long L=1;L*K<=n;L++){
        long long base=L*K;
        if(K>1 && z[L]<L*(K-1)) continue;
        long long ext= base<n? min<long long>(L,z[base]) : 0;
        d[base]++; d[min<long long>(n,base+ext)+1]--;
    }
    long long cnt=0,cur=0;
    for(int len=1;len<=n;len++){ cur+=d[len]; if(cur>0) cnt++; }
    return cnt;
}

