Node* del(Node* r,int k){
    if(!r) return r;
    if(k<r->val) r->left=del(r->left,k);
    else if(k>r->val) r->right=del(r->right,k);
    else {
        if(!r->left){ Node* t=r->right; delete r; return t; }
        if(!r->right){ Node* t=r->left; delete r; return t; }
        Node* s=r->right; while(s->left) s=s->left;
        r->val=s->val; r->right=del(r->right,s->val);
    }
    return r;
}
