vector<int> pathBST(Node* root,int a,int b){
    Node* c=root;
    while(c){ if(a<c->val&&b<c->val) c=c->left; else if(a>c->val&&b>c->val) c=c->right; else break; }
    vector<int> pa=downPath(c,a), pb=downPath(c,b);
