vector<int> topView(Node* root){
    map<int,int> top; queue<pair<Node*,int>> q; if(root) q.push({root,0});
    while(!q.empty()){
        auto [u,hd]=q.front(); q.pop();
        if(!top.count(hd)) top[hd]=u->val;
        if(u->left) q.push({u->left,hd-1});
        if(u->right) q.push({u->right,hd+1});
    }
    vector<int> res; for(auto& [h,v]: top) res.push_back(v);
    return res;
}

struct Node{ int val; Node *left=nullptr,*right=nullptr; Node(int v):val(v){} };
Node* deleteNode(Node* r,int key){
    if(!r) return nullptr;
    if(key<r->val) r->left=deleteNode(r->left,key);
    else if(key>r->val) r->right=deleteNode(r->right,key);
    else{
        if(!r->left){ Node* t=r->right; delete r; return t; }
        if(!r->right){ Node* t=r->left; delete r; return t; }
        Node* s=r->right; while(s->left) s=s->left;
        r->val=s->val; r->right=deleteNode(r->right,s->val);
    }
    return r;
}

int find(vector<int>& p,int x){ while(p[x]!=x) x=p[x]=p[p[x]]; return x; }
int largestSameComp(int n,const vector<int>& val,const vector<pair<int,int>>& edges){
    vector<int> p(n+1), sz(n+1,1); iota(p.begin(),p.end(),0);
    int best= n? 1:0;
    for(auto [u,v]: edges) if(val[u]==val[v]){
        int a=find(p,u), b=find(p,v); if(a==b) continue;
        if(sz[a]<sz[b]) swap(a,b); p[b]=a; sz[a]+=sz[b]; best=max(best,sz[a]);
    }
    return best;
}

long long layerPath(int n,const vector<long long>& L,const vector<vector<int>>& g){
    long long best=LLONG_MAX;
    vector<tuple<int,int,long long>> st={{1,0,0}};
    while(!st.empty()){
        auto [u,p,c]=st.back(); st.pop_back();
        bool leaf=true;
        for(int v: g[u]) if(v!=p){ leaf=false;
            if(L[v]>=L[u]) st.push_back({v,u,c+(L[v]-L[u])*(L[v]-L[u])}); }
        if(leaf) best=min(best,c);
    }
    return best==LLONG_MAX? -1 : best;
}

long long pw(long long b,long long e,long long m){ long long r=1; b%=m; while(e){ if(e&1) r=r*b%m; b=b*b%m; e>>=1; } return r; }
long long similarTrees(int n,const vector<int>& P){ // P[1..n], P[1]=0
    const long long MOD=1e9+7;
    vector<vector<int>> ch(n+1); for(int i=2;i<=n;i++) ch[P[i]].push_back(i);
    vector<int> dep(n+1,0), q={1}; vector<long long> cnt(n+1,0);
    for(size_t i=0;i<q.size();i++){ int u=q[i]; cnt[dep[u]]++;
        for(int v: ch[u]){ dep[v]=dep[u]+1; q.push_back(v); } }
    vector<long long> f(n+1,1); for(int i=1;i<=n;i++) f[i]=f[i-1]*i%MOD;
    long long ans=f[n-1];
    for(int d=1;d<=n;d++) if(cnt[d]) ans=ans*pw(f[cnt[d]],MOD-2,MOD)%MOD;
    return ans;
}

vector<long long> sumDistances(int n,const vector<vector<int>>& g){
    vector<int> par(n,-1), order={0}; par[0]=0;
    for(size_t i=0;i<order.size();i++) for(int v: g[order[i]]) if(par[v]==-1){ par[v]=order[i]; order.push_back(v); }
    vector<long long> sz(n,1), down(n,0), ans(n,0);
    for(int i=n-1;i>0;i--){ int v=order[i]; sz[par[v]]+=sz[v]; down[par[v]]+=down[v]+sz[v]; }
    ans[0]=down[0];
    for(int i=1;i<n;i++){ int v=order[i]; ans[v]=ans[par[v]]-sz[v]+(n-sz[v]); }
    return ans;
}

int minRemovals(int n,int K,const vector<vector<int>>& g){
    vector<int> par(n+1,0), order, pend(n+1,0);
    vector<int> st={1}; par[1]=-1;
    while(!st.empty()){ int u=st.back(); st.pop_back(); order.push_back(u);
        for(int v: g[u]) if(v!=par[u]){ par[v]=u; st.push_back(v); } }
    int removed=0;
    for(int i=n-1;i>=0;i--){ int u=order[i]; pend[u]+=1;
        if(pend[u]>=K){ removed++; pend[u]=0; }
        if(par[u]>0) pend[par[u]]+=pend[u]; }
    return removed;
}

long long realms(int n,const vector<int>& par){ // par[1..n], root has par<=0
    const long long MOD=1e9+7; vector<vector<int>> ch(n+1); int root=1;
    for(int v=1;v<=n;v++){ if(par[v]<=0) root=v; else ch[par[v]].push_back(v); }
    vector<int> ord={root}; for(size_t i=0;i<ord.size();i++) for(int c: ch[ord[i]]) ord.push_back(c);
    vector<vector<long long>> d0(n+1), d1(n+1);
    for(int i=n-1;i>=0;i--){ int v=ord[i]; vector<long long> a0={1,0}, a1={0,1};
        for(int c: ch[v]){ auto &b0=d0[c], &b1=d1[c]; int m=b0.size();
            vector<long long> n0(a0.size()+m,0), n1(a1.size()+m,0);
            for(size_t x=0;x<a0.size();x++) if(a0[x]) for(int y=0;y<m;y++) n0[x+y]=(n0[x+y]+a0[x]*((b0[y]+b1[y])%MOD))%MOD;
            for(size_t x=0;x<a1.size();x++) if(a1[x]) for(int y=0;y<m;y++){
                n1[x+y]=(n1[x+y]+a1[x]*b0[y])%MOD;
                if(x+y>0) n1[x+y-1]=(n1[x+y-1]+a1[x]*b1[y])%MOD; }
            while(n0.size()>2&&!n0.back()&&!n1.back()){ n0.pop_back(); n1.pop_back(); }
            n1.resize(n0.size()); a0.swap(n0); a1.swap(n1);
            vector<long long>().swap(b0); vector<long long>().swap(b1); }
        d0[v]=a0; d1[v]=a1; }
    vector<char> comp(n+1,0); long long ans=0;
    for(int x=2;x<=n;x++) if(!comp[x]){ for(long long y=1LL*x*x;y<=n;y+=x) comp[y]=1;
        if(x<(int)d0[root].size()) ans=(ans+d0[root][x]+d1[root][x])%MOD; }
    return ans;
}
